    <main id="auth-main" class="auth-main"><div class="auth-layout"><section class="auth-intro"><p class="eyebrow">Selva Electricals</p><h1>Everything you need for your next project.</h1><p>Save your estimates, keep trade details in one place, and get faster support from our Jaffna counter.</p><ul class="auth-benefits"><li><x-store-icon file="c4d46.svg" :size="20" /> Save products to your wishlist</li><li><x-store-icon file="50a88.svg" :size="20" /> Build and revisit quotations</li><li><x-store-icon file="49cd5.svg" :size="20" /> Get direct WhatsApp support</li></ul></section><section class="auth-card" aria-labelledby="auth-heading"><div class="auth-tabs" role="tablist" aria-label="Account access"><button id="login-tab" class="is-active" role="tab" aria-selected="true" aria-controls="login-panel">Sign in</button><button id="register-tab" role="tab" aria-selected="false" aria-controls="register-panel">Create account</button></div><div class="auth-card-content">@if ($errors->any())<div role="alert" style="padding:16px;background:#fff1f2;color:#9f1239;border-radius:8px;margin-bottom:16px">{{ $errors->first() }}</div>@endif<div id="login-panel" role="tabpanel" aria-labelledby="login-tab"><p class="auth-kicker">Welcome back</p><h2 id="auth-heading">Sign in to your account</h2><p class="auth-muted">Use your email and password to continue.</p><form class="auth-form" action="{{ route('login.store') }}" method="post">@csrf<label for="login-email">Email address</label><input id="login-email" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label for="login-password">Password</label><input id="login-password" name="password" type="password" autocomplete="current-password" minlength="8" required placeholder="Enter your password"><div class="auth-form-row"><label class="checkbox-label"><input type="checkbox" name="remember"> <span>Remember me</span></label><a href="#" data-demo-message="Password reset is available through our support desk.">Forgot password?</a></div><button class="button button-navy" type="submit">Sign in</button></form><p class="auth-switch">New to Selva Electricals? <button type="button" data-auth-tab="register">Create an account</button></p></div><div id="register-panel" role="tabpanel" aria-labelledby="register-tab" hidden><p class="auth-kicker">Join the Selva community</p><h2>Create your account</h2><p class="auth-muted">Register for quicker quotations and trade support.</p><form class="auth-form" action="{{ route('register.store') }}" method="post">@csrf<div class="auth-two-col"><div><label for="register-first-name">First name</label><input id="register-first-name" name="first_name" autocomplete="given-name" required></div><div><label for="register-last-name">Last name</label><input id="register-last-name" name="last_name" autocomplete="family-name" required></div></div><label for="register-email">Email address</label><input id="register-email" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label for="register-phone">Phone number</label><input id="register-phone" name="phone" type="tel" autocomplete="tel" required placeholder="+94 77 123 4567"><label for="register-password">Create password</label><input id="register-password" name="password" type="password" autocomplete="new-password" minlength="12" required placeholder="At least 12 characters"><label class="checkbox-label terms-label"><input type="checkbox" required> <span>I agree to receive order and quotation updates from Selva Electricals.</span></label><button class="button button-amber" type="submit">Create account</button></form><p class="auth-switch">Already have an account? <button type="button" data-auth-tab="login">Sign in</button></p></div></div></section></div></main><div class="toast" id="auth-toast" role="status" aria-live="polite" hidden></div>
    <script>
        const tabs = document.querySelectorAll('[role="tab"]');
        const panels = { login: document.querySelector('#login-panel'), register: document.querySelector('#register-panel') };
        const toast = document.querySelector('#auth-toast');
        const showAuthToast = message => { toast.textContent = message; toast.hidden = false; setTimeout(() => { toast.hidden = true; }, 3500); };
        const selectAuthTab = name => { tabs.forEach(tab => { const selected = tab.id === name + '-tab'; tab.classList.toggle('is-active', selected); tab.setAttribute('aria-selected', String(selected)); }); Object.entries(panels).forEach(([key, panel]) => { panel.hidden = key !== name; }); (panels[name].querySelector('input') || panels[name]).focus(); };
        tabs.forEach(tab => tab.addEventListener('click', () => selectAuthTab(tab.id.replace('-tab', ''))));
        document.querySelectorAll('[data-auth-tab]').forEach(button => button.addEventListener('click', () => selectAuthTab(button.dataset.authTab)));
        document.querySelectorAll('[data-demo-message]').forEach(link => link.addEventListener('click', event => { event.preventDefault(); showAuthToast(link.dataset.demoMessage); }));
        if (location.pathname === '/register') selectAuthTab('register');
    </script>
